CREATE SCHEMA IF NOT EXISTS clinical_private; REVOKE ALL ON SCHEMA clinical_private FROM PUBLIC,anon; GRANT USAGE ON SCHEMA clinical_private TO authenticated,service_role; ALTER FUNCTION public.hc_has_preview_access() SET SCHEMA clinical_private; CREATE OR REPLACE FUNCTION public.hc_is_member(_clinic uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT clinical_private.hc_has_preview_access() AND EXISTS(SELECT 1 FROM public.hc_members WHERE clinic_id=_clinic AND user_id=auth.uid()) $$; CREATE OR REPLACE FUNCTION public.hc_is_owner(_clinic uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT clinical_private.hc_has_preview_access() AND EXISTS(SELECT 1 FROM public.hc_members WHERE clinic_id=_clinic AND user_id=auth.uid() AND role='owner') $$; DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='hc_create_clinic'; EXECUTE replace(definition,'public.hc_has_preview_access()','clinical_private.hc_has_preview_access()'); END $$;